/*
 * prog30_escape_unescape
 *
 * The original binary implements two simple text transformations:
 *
 *   prog30_escape_unescape escape   <string>
 *       – prints <string> with the characters
 *         backslash, double‑quote, newline and tab escaped
 *         (\"  \\  \n  \t).
 *
 *   prog30_escape_unescape unescape <string>
 *       – interprets the same escape sequences and prints the
 *         resulting string.  Any unknown or malformed escape
 *         sequence causes the program to print "INVALID".
 *
 * If the command line does not contain at least two arguments,
 * if the mode is not one of the two supported strings, or if the
 * input string is longer than 1023 characters, the program prints
 * "USAGE".  An unsupported mode prints "INVALID_MODE".
 *
 * The implementation below follows the logic of the de‑compiled
 * state‑machine while keeping the code clear and idiomatic.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>

#define MAX_INPUT_LEN 1023   /* matches the check in the original binary */

/* --------------------------------------------------------------------- */
/* Escape: backslash, double‑quote, newline and tab are escaped.          */
/* --------------------------------------------------------------------- */
static char *escape_string(const char *src)
{
    size_t len = strlen(src);
    /* In the worst case every character becomes two characters. */
    char *dst = malloc(len * 2 + 1);
    if (!dst) return NULL;

    size_t j = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)src[i];
        switch (c) {
            case '\\': dst[j++] = '\\'; dst[j++] = '\\'; break;
            case '"':  dst[j++] = '\\'; dst[j++] = '"';  break;
            case '\n': dst[j++] = '\\'; dst[j++] = 'n';   break;
            case '\t': dst[j++] = '\\'; dst[j++] = 't';   break;
            default:    dst[j++] = c;                       break;
        }
    }
    dst[j] = '\0';
    return dst;
}

/* --------------------------------------------------------------------- */
/* Unescape: interpret the same four escape sequences.                  */
/* Returns NULL on any malformed or unknown escape sequence.            */
/* --------------------------------------------------------------------- */
static char *unescape_string(const char *src)
{
    size_t len = strlen(src);
    char *dst = malloc(len + 1);          /* result can never be longer */
    if (!dst) return NULL;

    size_t i = 0, j = 0;
    while (i < len) {
        if (src[i] == '\\') {
            if (i + 1 >= len) {          /* trailing backslash – invalid */
                free(dst);
                return NULL;
            }
            char nxt = src[i + 1];
            switch (nxt) {
                case '\\': dst[j++] = '\\'; break;
                case '"':  dst[j++] = '"';  break;
                case 'n':   dst[j++] = '\n'; break;
                case 't':   dst[j++] = '\t'; break;
                default:    /* unknown escape sequence */
                    free(dst);
                    return NULL;
            }
            i += 2;
        } else {
            dst[j++] = src[i++];
        }
    }
    dst[j] = '\0';
    return dst;
}

/* --------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT_LEN) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(mode, "escape") == 0) {
        char *out = escape_string(input);
        if (!out) return 1;               /* allocation failure */
        puts(out);
        free(out);
        return 0;
    }

    if (strcmp(mode, "unescape") == 0) {
        char *out = unescape_string(input);
        if (!out) {
            puts("INVALID");
            return 0;
        }
        puts(out);
        free(out);
        return 0;
    }

    /* Any other mode is unsupported */
    puts("INVALID_MODE");
    return 0;
}
